export function createRetryCache({ loader, ttlMs, now }) {
  const entries = new Map();

  return {
    get(key, options = {}) {
      const existing = entries.get(key);
      if (existing) {
        if (existing.status === 'pending') {
          return existing.promise;
        }
        if (existing.status === 'resolved' && now() < existing.expiresAt) {
          return existing.promise;
        }
      }

      let resolve, reject;
      const promise = new Promise((res, rej) => {
        resolve = res;
        reject = rej;
      });

      const entry = { status: 'pending', promise };
      entries.set(key, entry);

      Promise.resolve()
        .then(() => loader(key, options))
        .then(value => {
          entry.status = 'resolved';
          entry.value = value;
          entry.expiresAt = now() + ttlMs;
          resolve(value);
        })
        .catch(error => {
          entries.delete(key);
          reject(error);
        });

      return promise;
    },
  };
}
